"use client"

import * as React from "react"
import { Sign, type SignProps } from "@/components/ui/sign"
import type { SignShape } from "@/lib/0db/sign-shapes"

const shape: SignShape = {
  "word": "empty",
  "line": [
    [
      [
        "O",
        12,
        12,
        10,
        0,
        360
      ]
    ],
    [
      [
        "M",
        9,
        15
      ],
      [
        "L",
        15,
        9
      ]
    ]
  ]
}

function SignCircleSlashDots(props: Omit<SignProps, "shape" | "variant">) {
  return <Sign shape={shape} variant="dots" {...props} />
}

export { SignCircleSlashDots, shape }
